// deno-lint-ignore-file no-explicit-any
// Phase 2.7+2.8: WhatsApp bot menu, numbered replies and Kiswahili. Deliberately self-contained (structural
// types, no relative imports, no Deno globals) so the same file runs in the edge function AND in the app's
// unit tests (src/lib/bot-menu.test.ts).
//
// Everything is gated by feature.bot.menu per school. With the flag off prepareMenuTurn() returns null and
// the dispatcher takes exactly the path it took before: English only, no menu, no language memory.
//
// Replies are fixed templates in English or Kiswahili. Nothing here is generated by a model, and the
// numbers in a reply still come only from the tools' verified queries (these functions only format them).
// The Kiswahili wording is a first draft: have a native speaker review it before enabling the flag for a
// school (open item O-34).

export type Lang = "en" | "sw";

export interface MenuRpc {
  rpc(name: string, args?: Record<string, unknown>): PromiseLike<{ data: any; error: { message: string } | null }>;
}

export type MenuItemKey =
  | "fee_balance"
  | "attendance"
  | "report_card"
  | "statement"
  | "report_absence"
  | "change_number"
  | "agent";

export interface MenuFeatures {
  documents: boolean;
  guardianRequests: boolean;
}

/** The items shown, in order, for a school's enabled features. The numbers a guardian types follow this order. */
export function menuItems(f: MenuFeatures): MenuItemKey[] {
  const items: MenuItemKey[] = ["fee_balance", "attendance"];
  if (f.documents) items.push("report_card", "statement");
  if (f.guardianRequests) items.push("report_absence", "change_number");
  items.push("agent");
  return items;
}

const ITEM_LABEL: Record<Lang, Record<MenuItemKey, string>> = {
  en: {
    fee_balance: "Fee balance",
    attendance: "Attendance",
    report_card: "Report card (PDF)",
    statement: "Fee statement (PDF)",
    report_absence: "Tell the school my child will be absent",
    change_number: "Change my phone number",
    agent: "Talk to the school office",
  },
  sw: {
    fee_balance: "Salio la ada",
    attendance: "Mahudhurio",
    report_card: "Kadi ya matokeo (PDF)",
    statement: "Taarifa ya ada (PDF)",
    report_absence: "Julisha shule mtoto hatakuja",
    change_number: "Badilisha namba yangu ya simu",
    agent: "Ongea na ofisi ya shule",
  },
};

export function menuText(lang: Lang, f: MenuFeatures): string {
  const lines = menuItems(f).map((k, i) => `${i + 1}. ${ITEM_LABEL[lang][k]}`);
  return lang === "sw"
    ? `Karibu! Jibu kwa nambari:\n${lines.join("\n")}\nAndika 'English' kubadilisha lugha, au 'orodha' kuona orodha hii tena.`
    : `Hi! Reply with a number:\n${lines.join("\n")}\nType 'Kiswahili' for Kiswahili, or 'menu' to see this list again.`;
}

// ---- Small text catalog -------------------------------------------------------------------------------
// English strings that already exist in the dispatcher are reproduced exactly (a test pins them) so the
// menu-on English answer is identical to the old one.

const TEXT = {
  ack: {
    en: "I've passed your message to the school office -- someone will get back to you here on WhatsApp shortly.",
    sw: "Nimepeleka ujumbe wako kwa ofisi ya shule -- mtu atakujibu hapa WhatsApp hivi karibuni.",
  },
  disambiguate: {
    en: "You have more than one child with us ({names}). Please reply with the child's first name so I know who you mean.",
    sw: "Una zaidi ya mtoto mmoja shuleni ({names}). Tafadhali jibu kwa jina la kwanza la mtoto ili nijue unamaanisha nani.",
  },
  switched: {
    en: "Switched -- I'll answer about {name} from here. Ask me about fee balance or attendance.",
    sw: "Sawa -- nitajibu kuhusu {name} kuanzia sasa. Andika 'orodha' kuona chaguo.",
  },
  langSet: {
    en: "Okay, I'll reply in English from now on.",
    sw: "Sawa, nitajibu kwa Kiswahili kuanzia sasa.",
  },
  guideAbsence: {
    en: "To tell the school your child will be absent, send a message like: Mary will be absent tomorrow, fever",
    sw: "Kuijulisha shule kuwa mtoto hatakuja, tuma ujumbe kama huu: Mary hatakuja kesho, homa",
  },
  guideNumber: {
    en: "To ask the school to change your phone number, send: change my number to 0712345678. The office will confirm before anything changes.",
    sw: "Kuomba shule ibadilishe namba yako ya simu, tuma: badilisha namba yangu mpya 0712345678. Ofisi itathibitisha kabla ya mabadiliko yoyote.",
  },
} as const;

export type TextKey = keyof typeof TEXT;

export function chatText(lang: Lang, key: TextKey, vars: Record<string, string> = {}): string {
  return TEXT[key][lang].replace(/\{(\w+)\}/g, (_, k: string) => vars[k] ?? "");
}

// ---- Replies built from verified data (formatting only) ----------------------------------------------

export function feeBalanceText(lang: Lang, v: { name: string; balance: number }): string {
  const n = Math.abs(v.balance).toLocaleString();
  if (lang === "sw") {
    return v.balance <= 0
      ? `Akaunti ya ada ya ${v.name} imelipwa kikamilifu${v.balance < 0 ? ` (ziada ya KES ${n})` : ""}. Hakuna salio linalodaiwa.`
      : `Salio la ada la ${v.name} ni KES ${n}.`;
  }
  return v.balance <= 0
    ? `${v.name}'s fee account is fully paid up${v.balance < 0 ? ` (a credit of KES ${n})` : ""}. No outstanding balance.`
    : `${v.name}'s outstanding fee balance is KES ${v.balance.toLocaleString()}.`;
}

export function attendanceText(
  lang: Lang,
  v: { name: string; status: string; date: string; absences: number },
): string {
  const known = v.status === "present" ? "present" : v.status === "late" ? "late" : "absent";
  if (lang === "sw") {
    const label = known === "present" ? "alikuwepo" : known === "late" ? "alichelewa" : "hakuwepo";
    return `${v.name} alirekodiwa kuwa ${label} tarehe ${v.date}. Siku za kutokuwepo katika siku 30 zilizopita: ${v.absences}.`;
  }
  return `${v.name} was marked ${known} on ${v.date}. ${v.absences} absence(s) recorded in the last 30 days.`;
}

export function noAttendanceText(lang: Lang, name: string): string {
  return lang === "sw"
    ? `Sina rekodi zozote za mahudhurio za ${name} bado.`
    : `I don't have any attendance records for ${name} yet.`;
}

// ---- Understanding the guardian's message ------------------------------------------------------------

// Words that are clearly Kiswahili (not names or English words). "leo" and "sasa" are left out on purpose.
const SWAHILI_CUES = [
  "habari", "jambo", "mambo", "salio", "mahudhurio", "tafadhali", "asante", "naomba", "nataka", "mtoto",
  "mwanangu", "matokeo", "ripoti", "orodha", "msaada", "kesho", "hatakuja", "ninaomba", "shukrani", "pole",
];

export function looksSwahili(text: string): boolean {
  const t = text.toLowerCase();
  return SWAHILI_CUES.some((w) => new RegExp(`(^|[^a-z])${w}([^a-z]|$)`).test(t));
}

/** "Kiswahili" / "English" typed on their own set the language. */
export function languageCommand(text: string): Lang | null {
  const t = text.trim().toLowerCase().replace(/[.!]+$/, "");
  if (["kiswahili", "swahili", "sw"].includes(t)) return "sw";
  if (["english", "kiingereza", "en"].includes(t)) return "en";
  return null;
}

export function wantsMenu(text: string): boolean {
  return ["menu", "orodha", "0", "chaguo", "options"].includes(text.trim().toLowerCase().replace(/[.!?]+$/, ""));
}

export type MenuChoice =
  | { kind: "rewrite"; text: string } // run the normal pipeline as if the guardian had typed this
  | { kind: "guide"; key: "guideAbsence" | "guideNumber" }
  | null;

/** A single digit typed after the menu. Rewritten into the words the existing intents already understand. */
export function menuChoice(text: string, f: MenuFeatures): MenuChoice {
  const t = text.trim();
  if (!/^[1-9]$/.test(t)) return null;
  const key = menuItems(f)[Number(t) - 1];
  switch (key) {
    case "fee_balance": return { kind: "rewrite", text: "fee balance" };
    case "attendance": return { kind: "rewrite", text: "attendance" };
    case "report_card": return { kind: "rewrite", text: "report card" };
    case "statement": return { kind: "rewrite", text: "fee statement" };
    case "report_absence": return { kind: "guide", key: "guideAbsence" };
    case "change_number": return { kind: "guide", key: "guideNumber" };
    case "agent": return { kind: "rewrite", text: "agent" };
    default: return null;
  }
}

// ---- One turn ----------------------------------------------------------------------------------------

export interface MenuTurnInput {
  supabase: MenuRpc;
  schoolId: string;
  conversationId: string;
  messageText: string;
  documents: boolean;
  /** Only called for a single-word message, to recognise a child's first name. */
  getChildren(): Promise<{ student_id: string; first_name: string }[]>;
}

export interface MenuTurn {
  language: Lang;
  /** The text the rest of the dispatcher should work on (a menu number is rewritten into words). */
  text: string;
  features: MenuFeatures;
  /** When set, answer this directly and stop. */
  reply?: { text: string; studentId?: string | null };
}

async function rpcData(s: MenuRpc, name: string, args: Record<string, unknown>): Promise<any> {
  try {
    const { data, error } = await s.rpc(name, args);
    return error ? null : data;
  } catch {
    return null;
  }
}

/**
 * Returns null when the school does not have feature.bot.menu (fails closed on any error), so nothing
 * changes for that school. Otherwise works out the language, handles "menu", "Kiswahili"/"English", menu
 * numbers and a bare child's name, and tells the dispatcher what text to carry on with.
 */
export async function prepareMenuTurn(input: MenuTurnInput): Promise<MenuTurn | null> {
  const { supabase, schoolId, conversationId } = input;
  if ((await rpcData(supabase, "bot_menu_enabled", { p_school_id: schoolId })) !== true) return null;

  const guardianRequests = (await rpcData(supabase, "bot_guardian_requests_enabled", { p_school_id: schoolId })) === true;
  const features: MenuFeatures = { documents: input.documents, guardianRequests };

  const stored = await rpcData(supabase, "bot_get_language", { p_school_id: schoolId, p_conversation_id: conversationId });
  let language: Lang = stored === "sw" ? "sw" : "en";
  const setLanguage = async (lang: Lang) => {
    language = lang;
    await rpcData(supabase, "bot_set_language", { p_school_id: schoolId, p_conversation_id: conversationId, p_language: lang });
  };

  const raw = input.messageText;
  const turn = (extra: Partial<MenuTurn> = {}): MenuTurn => ({ language, text: raw, features, ...extra });

  const command = languageCommand(raw);
  if (command) {
    await setLanguage(command);
    return turn({ reply: { text: `${chatText(language, "langSet")}\n${menuText(language, features)}` } });
  }

  // A clearly Kiswahili message switches the conversation to Kiswahili (typing English switches back).
  if (language === "en" && looksSwahili(raw)) await setLanguage("sw");

  if (wantsMenu(raw)) return turn({ reply: { text: menuText(language, features) } });

  const choice = menuChoice(raw, features);
  if (choice?.kind === "guide") return turn({ reply: { text: chatText(language, choice.key) } });
  if (choice?.kind === "rewrite") return turn({ text: choice.text });

  // A single word that is one of the guardian's children's first names (the answer to "which child?").
  if (/^[A-Za-z'’-]{2,30}$/.test(raw.trim())) {
    const children = await input.getChildren();
    const word = raw.trim().toLowerCase();
    const hits = children.filter((c) => c.first_name.trim().toLowerCase() === word);
    if (hits.length === 1) {
      return turn({
        reply: {
          text: `${chatText(language, "switched", { name: hits[0].first_name })}\n${menuText(language, features)}`,
          studentId: hits[0].student_id,
        },
      });
    }
  }

  return turn();
}
